# tests/test_flatten_dict.py

import pytest

from your_module import flatten_dict  # Replace with the actual module name


def test_flatten_flat_dictionary():
    assert flatten_dict({"a": 1, "b": "two", "c": None}) == {
        "a": 1,
        "b": "two",
        "c": None,
    }


def test_flatten_nested_dictionary():
    data = {
        "user": {
            "name": "Ada",
            "address": {
                "city": "London",
                "postcode": "SW1A",
            },
        },
        "active": True,
    }

    assert flatten_dict(data) == {
        "user.name": "Ada",
        "user.address.city": "London",
        "user.address.postcode": "SW1A",
        "active": True,
    }


def test_flatten_with_custom_separator():
    assert flatten_dict({"a": {"b": {"c": 1}}}, sep="/") == {
        "a/b/c": 1,
    }


def test_flatten_with_parent_key():
    assert flatten_dict({"a": {"b": 1}, "c": 2}, parent_key="root") == {
        "root.a.b": 1,
        "root.c": 2,
    }


def test_empty_dictionary_returns_empty_dictionary():
    assert flatten_dict({}) == {}


def test_empty_nested_dictionaries_are_omitted():
    assert flatten_dict({"a": {}, "b": {"c": {}}, "d": 3}) == {
        "d": 3,
    }


def test_non_dict_values_are_not_flattened():
    list_value = [{"nested": "dict"}]

    data = {
        "a": list_value,
        "b": None,
        "c": {"d": (1, 2)},
    }

    assert flatten_dict(data) == {
        "a": list_value,
        "b": None,
        "c.d": (1, 2),
    }


def test_dict_subclass_values_are_flattened():
    class CustomDict(dict):
        pass

    data = {
        "a": CustomDict({"b": 1}),
    }

    assert flatten_dict(data) == {
        "a.b": 1,
    }


def test_original_dictionary_is_not_mutated():
    data = {"a": {"b": 1}}
    original = {"a": {"b": 1}}

    result = flatten_dict(data)

    assert result == {"a.b": 1}
    assert data == original


@pytest.mark.parametrize(
    ("data", "expected"),
    [
        ({"a": {"b": "nested"}, "a.b": "flat"}, {"a.b": "flat"}),
        ({"a.b": "flat", "a": {"b": "nested"}}, {"a.b": "nested"}),
    ],
)
def test_key_collisions_later_values_win(data, expected):
    # The implementation returns dict(items), so duplicate flattened keys
    # are overwritten by later entries.
    assert flatten_dict(data) == expected


def test_non_string_keys():
    data = {
        1: "one",
        "a": {
            2: "two",
        },
    }

    assert flatten_dict(data) == {
        1: "one",
        "a.2": "two",
    }


@pytest.mark.parametrize("bad_input", [None, [], "not a dict", 123])
def test_invalid_input_without_items_raises_attribute_error(bad_input):
    with pytest.raises(AttributeError):
        flatten_dict(bad_input)


def test_self_referential_dictionary_raises_recursion_error():
    data = {}
    data["self"] = data

    with pytest.raises(RecursionError):
        flatten_dict(data)
